-- F2-B7: Revision Recommendations
-- Generated by .tools/b7_sql_create.py

-- 1. revision_recommendations table
create table if not exists app_private.revision_recommendations (
  recommendation_id uuid primary key,
  user_id uuid not null references app_private.user_profiles(user_id) on delete restrict,
  material_id uuid not null,
  conversation_id uuid not null,
  pending_action_id uuid not null,
  candidate_id uuid,
  assessment_version text not null default '1.0.0' check (assessment_version = '1.0.0'),
  topic text not null check (length(btrim(topic)) > 0 and length(topic) <= 120),
  suggested_minutes integer not null check (suggested_minutes between 15 and 240),
  priority numeric not null check (priority in (0.1, 0.5, 1.0)),
  reason_summary text not null check (length(btrim(reason_summary)) > 0 and length(reason_summary) <= 1000),
  status text not null default 'PROPOSED' check (status in ('PROPOSED', 'ACCEPTED', 'REJECTED')),
  evidence jsonb not null,
  confidence_limit jsonb not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (user_id, recommendation_id),
  unique (user_id, pending_action_id),
  unique (user_id, candidate_id),
  constraint revision_recommendations_accepted_candidate_chk check (
    (status = 'ACCEPTED' and candidate_id is not null)
    or (status in ('PROPOSED', 'REJECTED') and candidate_id is null)
  ),
  foreign key (user_id, material_id) references app_private.materials(user_id, material_id),
  foreign key (user_id, conversation_id) references app_private.conversation_records(user_id, conversation_id),
  foreign key (user_id, pending_action_id) references app_private.pending_actions(user_id, action_id),
  foreign key (user_id, candidate_id) references app_private.task_candidates(user_id, candidate_id)
);

