create or replace function app_private.guard_revision_recommendations()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_valid integer;
  v_err integer;
  v_rate numeric;
begin
  if tg_op = 'DELETE' then
    raise exception 'Deleting revision_recommendations is forbidden' using errcode = '42501';
  end if;

  if tg_op = 'INSERT' then
    if new.status <> 'PROPOSED' or new.candidate_id is not null then
      raise exception 'Initial revision_recommendation must be PROPOSED with null candidate_id' using errcode = '23514';
    end if;
    if new.user_id <> app_private.current_uid() then
      raise exception 'Owner mismatch on insert' using errcode = '42501';
    end if;
  end if;

  if tg_op = 'UPDATE' then
    if old.status <> 'PROPOSED' or new.status not in ('ACCEPTED', 'REJECTED') then
      raise exception 'Invalid status transition from % to %', old.status, new.status using errcode = '23514';
    end if;
    if new.recommendation_id <> old.recommendation_id
       or new.user_id <> old.user_id
       or new.material_id <> old.material_id
       or new.conversation_id <> old.conversation_id
       or new.pending_action_id <> old.pending_action_id
       or new.assessment_version <> old.assessment_version
       or new.topic <> old.topic
       or new.suggested_minutes <> old.suggested_minutes
       or new.priority <> old.priority
       or new.reason_summary <> old.reason_summary
       or new.evidence is distinct from old.evidence
       or new.confidence_limit is distinct from old.confidence_limit
       or new.created_at <> old.created_at then
      raise exception 'Immutable fields on revision_recommendations cannot be modified' using errcode = '42501';
    end if;
    new.updated_at := now();
  end if;

  if not app_private.matches_contract('RecommendationEvidence', new.evidence) or not app_private.matches_contract('ConfidenceLimit', new.confidence_limit) then
    raise exception 'Invalid recommendation evidence contract' using errcode='23514';
  end if;
  -- Validate evidence and confidence_limit contracts
  v_valid := (new.evidence ->> 'valid_response_count')::integer;
  v_err := (new.evidence ->> 'error_count')::integer;
  v_rate := (new.evidence ->> 'error_rate')::numeric;

  if v_valid is null or v_valid <= 0 or v_err is null or v_err <= 0 or v_err > v_valid then
    raise exception 'Invalid evidence counts' using errcode = '23514';
  end if;
  if v_rate is null or abs(v_rate - (v_err::numeric / v_valid::numeric)) > 1e-12 then
    raise exception 'Invalid evidence error_rate' using errcode = '23514';
  end if;
  if coalesce(new.confidence_limit ->> 'level', '') <> 'LOW' then
    raise exception 'confidence_limit.level must be LOW' using errcode = '23514';
  end if;

  return new;
end;
$$;

alter function app_private.guard_revision_recommendations() owner to sf_rpc_owner;
revoke all on function app_private.guard_revision_recommendations() from public, anon, authenticated;

drop trigger if exists trg_revision_recommendations_guard on app_private.revision_recommendations;
create trigger trg_revision_recommendations_guard
  before insert or update or delete on app_private.revision_recommendations
  for each row execute function app_private.guard_revision_recommendations();

