-- B7 snapshot ratios round-trip through Python JSON floats; other number rules stay unchanged.
create or replace function app_private.canonical_json(p_value jsonb) returns text
language plpgsql immutable set search_path = '' as $$
declare
    v_type text := jsonb_typeof(p_value);
    v_text text;
begin
    if v_type = 'null' then
        return 'null';
    elsif v_type = 'boolean' then
        return p_value::text;
    elsif v_type = 'number' then
        v_text := p_value::text;
        if v_text !~ '^-?(0|[1-9][0-9]{0,15})$' or abs(v_text::numeric) > 9007199254740991 then
            raise exception using errcode = '22023',
                message = 'canonical JSON accepts only safe integers';
        end if;
        return v_text;
    elsif v_type = 'string' then
        return to_jsonb(p_value #>> '{}')::text;
    elsif v_type = 'array' then
        return '[' || coalesce((select string_agg(app_private.canonical_json(e.value), ',' order by e.ord)
                                from jsonb_array_elements(p_value) with ordinality e(value, ord)), '') || ']';
    end if;
    return '{' || coalesce((select string_agg(
        to_jsonb(e.key)::text || ':' ||
        case
            when e.key = 'priority' and jsonb_typeof(e.value) = 'number' and e.value::text in ('0.1', '0.5')
                then e.value::text
            when e.key = 'score_percent' and jsonb_typeof(e.value) = 'number'
                 and e.value::numeric >= 0 and e.value::numeric <= 100
                 and e.value::text ~ '^(0|[1-9][0-9]{0,2})(\.[0-9]{1,2})?$'
                then e.value::text
            when e.key = 'error_rate' and jsonb_typeof(e.value) = 'number'
                 and e.value::numeric >= 0 and e.value::numeric <= 1
                 and e.value::text ~ '^(0|1)(\.[0-9]{1,24})?$'
                then e.value::text
            else app_private.canonical_json(e.value)
        end,
        ',' order by convert_to(e.key, 'UTF8'))
        from jsonb_each(p_value) e), '') || '}';
end $$;

-- 3. Extend presentation_digest, store_presentation, claim_api_receipt, and api_request_receipts constraint
create or replace function app_private.presentation_digest(p_action app_private.pending_actions, p_target_type text,
                                                           p_target_id uuid, p_target_version bigint,
                                                           p_presentation jsonb) returns text
language sql immutable set search_path = '' as $$
    select encode(extensions.digest(convert_to(app_private.canonical_json(
        jsonb_build_object(
            'intent', p_action.intent, 'state', p_action.state, 'draft_arguments', p_action.draft_arguments,
            'missing_fields', p_action.missing_fields, 'ambiguities', p_action.ambiguities,
            'target_type', p_target_type, 'target_id', p_target_id, 'target_version', p_target_version,
            'candidate_slots', p_presentation #> '{candidate,slots}', 'proposal', p_presentation -> 'proposal',
            'normalized_command', p_presentation -> 'normalized_command',
            'effective_policy', p_presentation -> 'effective_policy'
        ) || case when p_presentation ? 'question_drafts'
                  then jsonb_build_object('question_drafts', p_presentation -> 'question_drafts')
                  else '{}'::jsonb end || case when p_presentation ? 'revision_recommendation' then jsonb_build_object('revision_recommendation', p_presentation -> 'revision_recommendation', 'revision_source_chunks', p_presentation -> 'revision_source_chunks') else '{}'::jsonb end
    ), 'UTF8'), 'sha256'), 'hex')
$$;

alter function app_private.presentation_digest(app_private.pending_actions, text, uuid, bigint, jsonb) owner to sf_rpc_owner;
revoke all on function app_private.presentation_digest(app_private.pending_actions, text, uuid, bigint, jsonb) from public, anon, authenticated;

create or replace function app_private.store_presentation(p_request jsonb, p_uid uuid, p_action app_private.pending_actions,
                                                           p_presentation jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
  r app_private.revision_recommendations;
  v_rec_found boolean := false;
    c app_private.task_candidates;
    v_type text;
    v_target uuid;
    v_target_version bigint;
    v_message uuid := (p_request #>> '{execution_context,trusted_context,message_id}')::uuid;
    v_stored jsonb;
    v_db_items jsonb;
    v_db_sources jsonb;
    v_non_draft int;
begin
    select * into r
  from app_private.revision_recommendations rec
  where rec.user_id = p_uid
    and (
      rec.pending_action_id = p_action.action_id
      or (p_action.candidate_id is not null and rec.candidate_id = p_action.candidate_id)
    )
  limit 1;
  v_rec_found := found;

  if p_action.intent = 'ACCEPT_REVISION_RECOMMENDATION' and not v_rec_found then
    raise exception 'Revision recommendation not found for action %', p_action.action_id using errcode = 'P0002';
  end if;

  if v_rec_found then
    if coalesce(p_presentation -> 'revision_recommendation', 'null'::jsonb) is distinct from app_private.revision_json(r) then
      raise exception 'Presented revision_recommendation does not match stored record' using errcode = 'P0001';
    end if;
    if coalesce(p_presentation -> 'revision_source_chunks', '[]'::jsonb) is distinct from app_private.revision_source_chunks(p_uid, r.evidence) then
      raise exception 'Presented revision_source_chunks do not match stored record' using errcode = 'P0001';
    end if;
  else
    if p_presentation ? 'revision_recommendation'
       and (p_presentation -> 'revision_recommendation') is not null
       and (p_presentation -> 'revision_recommendation') <> 'null'::jsonb then
      raise exception 'Unexpected revision_recommendation in presentation' using errcode = 'P0001';
    end if;
  end if;

  if p_action.candidate_id is not null then
        select * into c from app_private.task_candidates where user_id = p_uid and candidate_id = p_action.candidate_id;
        if not found then
            return app_private.error_result(p_request, 'ENTITY_NOT_FOUND', 'The candidate was not found.');
        end if;
        if p_presentation -> 'candidate' is null or p_presentation -> 'candidate' = 'null'::jsonb
           or c.status <> 'DRAFT'
           or (c.version, c.slots) is distinct from ((p_presentation #>> '{candidate,version}')::bigint, p_presentation #> '{candidate,slots}') then
            return app_private.error_result(p_request, 'STALE_ENTITY_VERSION', 'The presented candidate no longer matches the draft.');
        end if;
        v_type := 'TASK_CANDIDATE'; v_target := c.candidate_id; v_target_version := c.version;
    elsif p_action.proposal_id is not null then
        select p.version into v_target_version from app_private.plan_proposals p
        where p.user_id = p_uid and p.proposal_id = p_action.proposal_id and p.status = 'PROPOSED';
        if v_target_version is null then
            return app_private.error_result(p_request, 'ENTITY_NOT_FOUND', 'The proposal was not found or is no longer pending.');
        end if;
        v_type := 'PLAN_PROPOSAL'; v_target := p_action.proposal_id;
    elsif p_action.intent = 'VERIFY_QUESTION_DRAFTS' then
        select coalesce(jsonb_agg(app_private.question_json(q) order by bi.item_order), '[]'::jsonb),
               count(*) filter (where q.status <> 'DRAFT')
        into v_db_items, v_non_draft
        from app_private.question_draft_batch_items bi
        join app_private.question_drafts q on q.user_id = bi.user_id and q.question_id = bi.question_id
        where bi.user_id = p_uid and bi.action_id = p_action.action_id;
        v_db_sources := app_private.question_batch_source_chunks(p_uid, p_action.action_id);
        if jsonb_array_length(v_db_items) = 0 or jsonb_array_length(v_db_sources) = 0 or coalesce(v_non_draft, 0) > 0
           or (p_presentation #> '{question_drafts,items}') is distinct from v_db_items
           or (p_presentation #> '{question_drafts,source_chunks}') is distinct from v_db_sources then
            return app_private.error_result(p_request, 'STALE_ENTITY_VERSION', 'The presented question drafts no longer match the stored batch.');
        end if;
        v_type := 'PENDING_ACTION'; v_target := p_action.action_id; v_target_version := p_action.version;
    else
        v_type := 'PENDING_ACTION'; v_target := p_action.action_id; v_target_version := p_action.version;
    end if;
    v_stored := jsonb_set(p_presentation, '{pending_action}', app_private.pending_json(p_action));
    insert into app_private.action_presentations
        (user_id, action_id, action_version, target_type, target_id, target_version, content_digest, presentation,
         source_message_id)
    values (p_uid, p_action.action_id, p_action.version, v_type, v_target, v_target_version,
            app_private.presentation_digest(p_action, v_type, v_target, v_target_version, v_stored), v_stored,
            case when exists (select 1 from app_private.source_messages m where m.user_id = p_uid and m.message_id = v_message)
                 then v_message end);
    return null;
end $$;

alter function app_private.store_presentation(jsonb, uuid, app_private.pending_actions, jsonb) owner to sf_rpc_owner;
revoke all on function app_private.store_presentation(jsonb, uuid, app_private.pending_actions, jsonb) from public, anon, authenticated;

alter table app_private.api_request_receipts
  drop constraint if exists api_request_receipts_http_operation_check;

alter table app_private.api_request_receipts
  add constraint api_request_receipts_http_operation_check
  check (
    http_operation in (
      'send_message',
      'prepare_action',
      'review_action',
      'submit_decision',
      'generate_question_drafts',
      'create_revision_recommendation'
    )
  );

create or replace function app_api.claim_api_receipt(p_request jsonb) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare
    v_error jsonb := app_private.precheck(p_request, 'claim_api_receipt', 'ClaimApiReceiptArguments');
    v_uid uuid;
    v_args jsonb := p_request -> 'arguments';
    v_now timestamptz := clock_timestamp();
    r app_private.api_request_receipts;
begin
    if v_error is not null then
        return v_error;
    end if;
    v_uid := app_private.current_uid();
    if p_request #>> '{execution_context,conversation_id}' is distinct from v_args ->> 'conversation_id' then
        return app_private.error_result(p_request, 'INVALID_PARAMETER', 'The conversation does not match the request context.');
    end if;
    begin
        perform app_private.lock_owner(v_uid, p_request);
        select * into r from app_private.api_request_receipts
        where user_id = v_uid and http_operation = v_args ->> 'http_operation'
          and idempotency_key = v_args ->> 'idempotency_key';
        if not found then
            insert into app_private.api_request_receipts
                (user_id, http_operation, idempotency_key, request_fingerprint, state, lease_version,
                 lease_until, message_id, action_id)
            values (v_uid, v_args ->> 'http_operation', v_args ->> 'idempotency_key',
                    v_args ->> 'request_fingerprint', 'IN_PROGRESS', 1, v_now + interval '120 seconds',
                    extensions.gen_random_uuid(),
                    case when v_args ->> 'http_operation' in ('send_message', 'prepare_action', 'generate_question_drafts', 'create_revision_recommendation')
                         then extensions.gen_random_uuid() end)
            returning * into r;
        elsif r.request_fingerprint <> v_args ->> 'request_fingerprint' then
            return app_private.error_result(p_request, 'IDEMPOTENCY_CONFLICT',
                'The idempotency key was already used with a different request.');
        elsif r.state = 'IN_PROGRESS' then
            if r.lease_until > v_now then
                return app_private.error_result(p_request, 'SERVICE_UNAVAILABLE',
                    'The same request is still being processed.', true);
            end if;
            update app_private.api_request_receipts
            set lease_version = lease_version + 1, lease_until = v_now + interval '120 seconds'
            where user_id = r.user_id and http_operation = r.http_operation and idempotency_key = r.idempotency_key
            returning * into r;
        end if;
        return app_private.ok_result(p_request, 'COMMITTED', app_private.receipt_json(r));
    exception when others then
        return app_private.failure(p_request, sqlstate);
    end;
end $$;

alter function app_api.claim_api_receipt(jsonb) owner to sf_rpc_owner;
revoke all on function app_api.claim_api_receipt(jsonb) from public, anon;
grant execute on function app_api.claim_api_receipt(jsonb) to authenticated;

-- 4. create_revision_recommendation RPC
create or replace function app_api.create_revision_recommendation(p_request jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_err jsonb;
  v_uid uuid;
  v_args jsonb;
  v_ctx jsonb;
  v_conv_id uuid;
  v_idem_key text;
  v_rec_id uuid;
  v_action_id uuid;
  v_mat_id uuid;
  v_topic text;
  v_minutes integer;
  v_priority numeric;
  v_fp text;
  v_saved jsonb;
  v_mat app_private.materials;
  v_valid_count integer := 0;
  v_error_count integer := 0;
  v_distinct_q_count integer := 0;
  v_attempt_ids jsonb := '[]'::jsonb;
  v_wrong_q_ids uuid[] := '{}'::uuid[];
  v_chunk_ids jsonb := '[]'::jsonb;
  v_total_source_count integer := 0;
  v_error_rate numeric;
  v_limitations jsonb := '[]'::jsonb;
  v_reason text;
  v_evidence jsonb;
  v_confidence jsonb;
  v_action app_private.pending_actions;
  v_rec app_private.revision_recommendations;
  v_sources jsonb;
  v_presentation jsonb;
  v_stored jsonb;
  v_result jsonb;
begin
  v_err := app_private.precheck(p_request, 'create_revision_recommendation', 'CreateRevisionRecommendationArguments');
  if v_err is not null then
    return v_err;
  end if;

  v_uid := app_private.current_uid();
  v_args := p_request -> 'arguments';
  v_ctx := p_request -> 'execution_context';

  v_idem_key := nullif(btrim(coalesce(v_ctx ->> 'idempotency_key', '')), '');
  if v_idem_key is null then
    return app_private.error_result(p_request, 'INVALID_PARAMETER', 'Thiếu idempotency_key.');
  end if;

  begin
    v_conv_id := (v_ctx ->> 'conversation_id')::uuid;
  exception when others then
    return app_private.error_result(p_request, 'INVALID_PARAMETER', 'conversation_id không hợp lệ.');
  end;
  if v_conv_id is null then
    return app_private.error_result(p_request, 'INVALID_PARAMETER', 'Thiếu conversation_id.');
  end if;

  v_rec_id := (v_args ->> 'recommendation_id')::uuid;
  v_action_id := (v_args ->> 'pending_action_id')::uuid;
  v_mat_id := (v_args ->> 'material_id')::uuid;
  v_topic := v_args ->> 'topic';
  v_minutes := (v_args ->> 'suggested_minutes')::integer;
  v_priority := (v_args ->> 'priority')::numeric;

  v_fp := app_private.domain_fingerprint(
    v_uid,
    'create_revision_recommendation',
    jsonb_build_object(
      'conversation_id', v_conv_id,
      'material_id', v_mat_id,
      'topic', v_topic,
      'suggested_minutes', v_minutes,
      'priority', v_priority
    )
  );

  v_saved := app_private.idempotent_reply(p_request, v_uid, 'create_revision_recommendation', v_idem_key, v_fp);
  if v_saved is not null then
    return v_saved;
  end if;

  perform app_private.lock_owner(v_uid, p_request);

  v_saved := app_private.idempotent_reply(p_request, v_uid, 'create_revision_recommendation', v_idem_key, v_fp);
  if v_saved is not null then
    return v_saved;
  end if;

  select * into v_mat
  from app_private.materials m
  where m.user_id = v_uid
    and m.material_id = v_mat_id
    and m.conversation_id = v_conv_id
    and m.status = 'READY';

  if not found then
    return app_private.error_result(p_request, 'ENTITY_NOT_FOUND', 'Không tìm thấy tài liệu sẵn sàng trong cuộc trò chuyện này.');
  end if;

  if not (v_mat.topics ? v_topic) then
    return app_private.error_result(p_request, 'INVALID_PARAMETER', 'Chủ đề không thuộc tài liệu đã chọn.');
  end if;

  if exists (
    select 1
    from app_private.pending_actions pa
    where pa.user_id = v_uid
      and pa.conversation_id = v_conv_id
      and pa.state in ('AWAITING_APPROVAL', 'AWAITING_CONFIRMATION', 'AWAITING_CLARIFICATION')
  ) then
    return app_private.error_result(p_request, 'ACTION_REVIEW_REQUIRED', 'Đang có hành động chờ xác nhận trong cuộc trò chuyện này.');
  end if;

  with eligible_attempts as (
    select qa.attempt_id, qa.submitted_at, qa.question_ids
    from app_private.quiz_attempts qa
    where qa.user_id = v_uid
      and qa.material_id = v_mat_id
      and qa.status = 'SUBMITTED'
      and exists (
        select 1
        from app_private.quiz_responses qr
        join app_private.question_drafts qd
          on qd.user_id = v_uid
         and qd.question_id = qr.question_id
        where qr.user_id = v_uid
          and qr.attempt_id = qa.attempt_id
          and qr.validity = 'VALID' and qr.graded_at is not null and qr.is_correct is not null
          and qd.material_id = v_mat_id
          and qd.topic = v_topic
          and qd.status = 'VERIFIED'
          and qa.question_ids ? qr.question_id::text
      )
    order by qa.submitted_at desc, qa.attempt_id desc
    limit 50
  ),
  eligible_responses as (
    select
      ea.attempt_id,
      ea.submitted_at,
      qr.question_id,
      qr.is_correct
    from eligible_attempts ea
    join app_private.quiz_responses qr
      on qr.user_id = v_uid
     and qr.attempt_id = ea.attempt_id
    join app_private.question_drafts qd
      on qd.user_id = v_uid
     and qd.question_id = qr.question_id
    where qr.validity = 'VALID' and qr.graded_at is not null and qr.is_correct is not null
      and qd.material_id = v_mat_id
      and qd.topic = v_topic
      and qd.status = 'VERIFIED'
      and ea.question_ids ? qr.question_id::text
  )
  select
    count(*)::integer,
    count(*) filter (where not er.is_correct)::integer,
    count(distinct er.question_id)::integer,
    coalesce((select jsonb_agg(ea.attempt_id order by ea.submitted_at desc, ea.attempt_id desc) from eligible_attempts ea), '[]'::jsonb),
    coalesce(array_agg(distinct er.question_id) filter (where not er.is_correct), '{}'::uuid[])
  into v_valid_count, v_error_count, v_distinct_q_count, v_attempt_ids, v_wrong_q_ids
  from eligible_responses er;

  if v_valid_count = 0 then
    return app_private.error_result(p_request, 'INVALID_PARAMETER', 'Chưa có dữ liệu làm bài hợp lệ cho chủ đề này.');
  end if;

  if v_error_count = 0 then
    return app_private.error_result(p_request, 'INVALID_PARAMETER', 'Chưa ghi nhận câu trả lời sai nào cho chủ đề này.');
  end if;

  with distinct_sources as (
    select distinct mc.chunk_id, mc.page, mc.chunk_index
    from app_private.question_draft_sources qds
    join app_private.material_chunks mc
      on mc.user_id = v_uid
     and mc.material_id = v_mat_id
     and mc.chunk_id = qds.chunk_id
    where qds.user_id = v_uid
      and qds.material_id = v_mat_id
      and qds.question_id = any(v_wrong_q_ids)
      and mc.topic = v_topic
  ),
  limited_sources as (
    select ds.chunk_id, ds.page, ds.chunk_index
    from distinct_sources ds
    order by ds.page asc, ds.chunk_index asc, ds.chunk_id asc
    limit 50
  )
  select
    (select count(*)::integer from distinct_sources),
    coalesce((select jsonb_agg(ls.chunk_id order by ls.page asc, ls.chunk_index asc, ls.chunk_id asc) from limited_sources ls), '[]'::jsonb)
  into v_total_source_count, v_chunk_ids;

  if v_total_source_count = 0 then
    return app_private.error_result(p_request, 'INVALID_PARAMETER', 'Không tìm thấy đoạn tài liệu nguồn liên quan đến các câu trả lời sai.');
  end if;

  v_error_rate := v_error_count::numeric / v_valid_count::numeric;

  v_evidence := jsonb_build_object(
    'valid_response_count', v_valid_count,
    'error_count', v_error_count,
    -- Store the wire float representation so Python review round trips preserve the snapshot.
    'error_rate', to_jsonb(v_error_count::double precision / v_valid_count::double precision),
    'chunk_ids', v_chunk_ids,
    'attempt_ids', v_attempt_ids
  );

  v_limitations := jsonb_build_array(
    'Chỉ tổng hợp tối đa 50 lượt làm bài gần nhất, không phản ánh toàn bộ lịch sử học tập.',
    format('Dựa trên %s lượt trả lời hợp lệ (%s lỗi) qua %s lượt làm bài.', v_valid_count, v_error_count, jsonb_array_length(v_attempt_ids)),
    'Chỉ phản ánh các đoạn tài liệu đã được kiểm tra, không đo lường toàn bộ mức độ thành thạo.'
  );

  if v_valid_count > v_distinct_q_count then
    v_limitations := v_limitations || jsonb_build_array('Có câu hỏi được lặp lại nhiều lần trong mẫu thống kê.');
  end if;

  if v_total_source_count > 50 then
    v_limitations := v_limitations || jsonb_build_array('Danh sách đoạn tài liệu nguồn đã được giới hạn tối đa 50 đoạn.');
  end if;

  v_confidence := jsonb_build_object(
    'level', 'LOW',
    'limitations', v_limitations
  );

  v_reason := format(
    'Ghi nhận %s/%s câu trả lời sai (%s%%) ở chủ đề "%s". Thời lượng %s phút và mức ưu tiên %s do người dùng chọn.',
    v_error_count,
    v_valid_count,
    round(v_error_rate * 100, 1),
    v_topic,
    v_minutes,
    v_priority
  );

  begin
    insert into app_private.pending_actions (
      action_id,
      user_id,
      conversation_id,
      intent,
      state,
      version,
      requires_review,
      draft_arguments,
      missing_fields,
      ambiguities,
      candidate_id,
      proposal_id,
      depends_on_action_id
    ) values (
      v_action_id,
      v_uid,
      v_conv_id,
      'ACCEPT_REVISION_RECOMMENDATION',
      'AWAITING_APPROVAL',
      1,
      false,
      jsonb_build_object('recommendation_id', v_rec_id),
      '[]'::jsonb,
      '[]'::jsonb,
      null,
      null,
      null
    ) returning * into v_action;

    insert into app_private.revision_recommendations (
      recommendation_id,
      user_id,
      material_id,
      conversation_id,
      pending_action_id,
      candidate_id,
      assessment_version,
      topic,
      suggested_minutes,
      priority,
      reason_summary,
      status,
      evidence,
      confidence_limit
    ) values (
      v_rec_id,
      v_uid,
      v_mat_id,
      v_conv_id,
      v_action_id,
      null,
      '1.0.0',
      v_topic,
      v_minutes,
      v_priority,
      v_reason,
      'PROPOSED',
      v_evidence,
      v_confidence
    ) returning * into v_rec;

    v_sources := app_private.revision_source_chunks(v_uid, v_rec.evidence);

    v_presentation := jsonb_build_object(
      'kind', 'ACTION_PRESENTATION',
      'pending_action', app_private.pending_json(v_action),
      'candidate', null,
      'proposal', null,
      'normalized_command', null,
      'effective_policy', null,
      'schedule_confirmation', null,
      'revision_recommendation', app_private.revision_json(v_rec),
      'revision_source_chunks', v_sources
    );

    v_err := app_private.store_presentation(p_request, v_uid, v_action, v_presentation);
    if v_err is not null then raise exception using errcode='P0001', message=v_err #>> '{error,code}'; end if;
    select presentation into v_stored from app_private.action_presentations where user_id=v_uid and action_id=v_action.action_id and action_version=v_action.version;
    v_result := app_private.ok_result(p_request, 'COMMITTED', v_stored);

    insert into app_private.idempotency_records (
      user_id,
      operation,
      idempotency_key,
      request_fingerprint,
      state,
      result_reference_or_response,
      expires_at
    ) values (
      v_uid,
      'create_revision_recommendation',
      v_idem_key,
      v_fp,
      'COMPLETED',
      v_result,
      now() + interval '7 days'
    );

    return v_result;
  exception when others then
    return app_private.failure(p_request, sqlstate);
  end;
end;
$$;

alter function app_api.create_revision_recommendation(jsonb) owner to sf_rpc_owner;
revoke all on function app_api.create_revision_recommendation(jsonb) from public, anon;
grant execute on function app_api.create_revision_recommendation(jsonb) to authenticated;
